import { randomUUID } from 'node:crypto';
import { expect, type APIRequestContext, type Page, request } from '@playwright/test';
import { API_BASE_URL, route } from '../origin';
import {
  DEV_ADMIN_EMAIL,
  DEV_ADMIN_NAME,
  DEV_ADMIN_PASSWORD,
  E2E_EMAIL_PREFIX,
} from './accounts';

/**
 * What an admin spec needs: an operator to sign in as, and real orders to work.
 *
 * ## Orders are placed through the API, not typed into the database
 *
 * `placeOrder` registers a customer, saves an address, fills a cart and posts
 * `POST /orders` — the same calls, in the same order, that the storefront's own
 * checkout makes. An order written straight into Mongo would be a guess about
 * what an order looks like, and it would go stale the first time the model
 * changed, silently, because nothing type-checks an `insertOne`.
 *
 * This is the DATA PATH the storefront uses. The storefront's own UI walk is
 * covered by its suite; what these specs prove is that an order created that
 * way is visible to, and operable from, this console.
 */

/*
 * Re-exported for the specs, which read them as the expected on-screen values.
 * Defined in `./accounts.ts` so the teardown can see the same list — see that
 * file for what keeping them here alone cost.
 */
export { DEV_ADMIN_EMAIL, DEV_ADMIN_NAME, DEV_ADMIN_PASSWORD };

/** Long enough for the API's policy, and not a value that appears in the repo twice. */
const CUSTOMER_PASSWORD = 'lithium polymer harness';

export interface PlacedOrder {
  readonly id: string;
  readonly orderNumber: string;
  readonly grandTotalFormatted: string;
  readonly customerEmail: string;
}

/**
 * An API context that does NOT use `baseURL`.
 *
 * `API_BASE_URL` carries a path prefix (`/api/v1`), and Playwright resolves a
 * request path against the base URL with `new URL()` — where an absolute path
 * REPLACES the whole path component. `post('/auth/register')` against a base of
 * `http://host:3002/api/v1` therefore hits `http://host:3002/auth/register`,
 * which is a 404 that reads like a missing endpoint.
 *
 * It is the same trap the admin's own `baseURL` has with `basePath` — noted in
 * `playwright.config.ts` — and it caught this fixture too. Every call below
 * builds the full URL with `url()`.
 */
async function api(): Promise<APIRequestContext> {
  return request.newContext();
}

/**
 * Asserts a status and, on failure, says what the API actually answered.
 *
 * A bare `expect(status).toBe(200)` reports "Received: 409" and nothing else,
 * which sends whoever is reading it guessing at which of several conflicts it
 * was. The API's envelope names the code; printing it turns a debugging round
 * into a sentence.
 */
async function expectStatus(
  response: import('@playwright/test').APIResponse,
  status: number,
  what: string,
): Promise<void> {
  if (response.status() === status) return;

  const body = await response.text();

  throw new Error(
    `${what}: expected HTTP ${String(status)}, got ${String(response.status())}
${body.slice(0, 400)}`,
  );
}

/** A full API URL. Never a bare path — see `api()`. */
function url(path: string): string {
  return `${API_BASE_URL}${path}`;
}

/**
 * Signs the operator in through the REAL form.
 *
 * Not by setting a cookie: the cookie is httpOnly and its value is a token this
 * suite has no business minting. Driving the form also means every spec
 * exercises the server action, the API call and the cookie write that a real
 * sign-in does — if any of those breaks, every spec fails rather than one.
 */
export async function signIn(
  page: Page,
  credentials: { email: string; password: string } = {
    email: DEV_ADMIN_EMAIL,
    password: DEV_ADMIN_PASSWORD,
  },
): Promise<void> {
  await page.goto(route('/login'));
  await page.getByLabel('Email Address').fill(credentials.email);
  await page.getByLabel('Password').fill(credentials.password);
  await page.getByRole('button', { name: /sign in/i }).click();
}

/** Signs in and waits until the console is actually showing. */
export async function signInAsAdmin(page: Page): Promise<void> {
  await signIn(page);
  await page.waitForURL((url) => !url.pathname.endsWith('/login'), { timeout: 30_000 });
}

/**
 * Places one REAL order through the API and returns what the console should
 * show for it.
 *
 * Each call creates its own customer, so orders never collide and a spec that
 * drives one order to a terminal state cannot affect another.
 */
export async function placeOrder(runId: string, label: string): Promise<PlacedOrder> {
  const context = await api();

  try {
    const email = `${E2E_EMAIL_PREFIX}.${label}.${runId}@example.test`;

    const registered = await context.post(url('/auth/register'), {
      data: { email, password: CUSTOMER_PASSWORD, fullName: `Admin E2E ${label}` },
    });
    await expectStatus(registered, 201, 'registering the order’s customer');

    const loggedIn = await context.post(url('/auth/login'), {
      data: { email, password: CUSTOMER_PASSWORD },
    });
    await expectStatus(loggedIn, 200, 'signing that customer in');

    const token = (await loggedIn.json()).data.accessToken as string;
    const auth = { Authorization: `Bearer ${token}` };

    const address = await context.post(url('/users/me/addresses'), {
      headers: auth,
      data: {
        label: 'Home',
        fullName: `Admin E2E ${label}`,
        phone: '01012345678',
        street: '12 Sherif Street, Apartment 4',
        city: 'Downtown',
        governorate: 'Cairo',
      },
    });
    await expectStatus(address, 201, 'saving a delivery address');
    const addressId = (await address.json()).data.id as string;

    /*
     * A real product from the seeded catalogue, chosen by asking the API rather
     * than by hard-coding a slug: a fixed slug is a spec that fails the day the
     * seed changes, for a reason that has nothing to do with the console.
     */
    const products = await context.get(url('/products?limit=24&sort=newest'));
    await expectStatus(products, 200, 'reading the catalogue');

    /*
     * A product that is IN STOCK, not merely the newest.
     *
     * The first version took `?limit=1&sort=newest`, which is the same product
     * on every call — so a run placing a dozen orders of it eventually drained
     * the stock, and every later spec failed with a `409` on the cart, several
     * files away from anything to do with the console. Choosing an available
     * one from a page makes the fixture independent of how many orders the run
     * has already placed.
     */
    const catalogue = (await products.json()).data as {
      id: string;
      availability: string;
    }[];

    const product = catalogue.find((candidate) => candidate.availability === 'IN_STOCK');

    if (product === undefined) {
      throw new Error(
        `No IN_STOCK product among the ${String(catalogue.length)} returned, so no order can ` +
          'be placed.\nRun: pnpm --filter api seed',
      );
    }

    const added = await context.post(url('/cart/items'), {
      headers: auth,
      data: { productId: product.id, quantity: 1 },
    });
    await expectStatus(added, 200, 'adding a line to the cart');

    const placed = await context.post(url('/orders'), {
      /*
       * A UUID, because the API requires one — `Idempotency-Key must be a UUID`.
       * Fresh per call: the key is the thing that makes a RETRY safe, so reusing
       * one across orders would make the second placement a replay of the first
       * and return the wrong order.
       */
      headers: { ...auth, 'Idempotency-Key': randomUUID() },
      data: { addressId },
    });
    await expectStatus(placed, 201, 'placing the order');

    const order = (await placed.json()).data as {
      id: string;
      orderNumber: string;
      pricing: { grandTotal: { formatted: string } };
    };

    return {
      id: order.id,
      orderNumber: order.orderNumber,
      grandTotalFormatted: order.pricing.grandTotal.formatted,
      customerEmail: email,
    };
  } finally {
    await context.dispose();
  }
}

/** Registers a CUSTOMER and returns their credentials. For the role tests. */
export async function registerCustomer(
  runId: string,
  label: string,
): Promise<{ email: string; password: string }> {
  const context = await api();

  try {
    const email = `${E2E_EMAIL_PREFIX}.${label}.${runId}@example.test`;

    const registered = await context.post(url('/auth/register'), {
      data: { email, password: CUSTOMER_PASSWORD, fullName: `Customer ${label}` },
    });
    await expectStatus(registered, 201, 'registering a customer');

    return { email, password: CUSTOMER_PASSWORD };
  } finally {
    await context.dispose();
  }
}

/** Reads one order as the API sees it, for asserting against what the UI shows. */
export async function readOrderAsAdmin(orderId: string): Promise<Record<string, unknown>> {
  const context = await api();

  try {
    const loggedIn = await context.post(url('/auth/login'), {
      data: { email: DEV_ADMIN_EMAIL, password: DEV_ADMIN_PASSWORD },
    });
    await expectStatus(loggedIn, 200, 'signing the development admin in');

    const token = (await loggedIn.json()).data.accessToken as string;

    const order = await context.get(url(`/admin/orders/${orderId}`), {
      headers: { Authorization: `Bearer ${token}` },
    });
    await expectStatus(order, 200, 'reading the order as staff');

    return (await order.json()).data as Record<string, unknown>;
  } finally {
    await context.dispose();
  }
}

import type { FullResult, Reporter, TestCase, TestResult } from '@playwright/test/reporter';

/**
 * Prints what the browser-health fixture chose to ignore, and why.
 *
 * ## Why a reporter and not a `console.log` in the fixture
 *
 * The fixture runs once per test, in a worker process. A line printed there is
 * one line per test, interleaved with the test output, and says nothing about
 * the run as a whole — which is the only level at which "is the ignore list
 * growing?" is a meaningful question. A reporter runs in the main process and
 * sees every test, so it can answer it once, at the end, where somebody will
 * read it.
 *
 * ## Why it exists at all
 *
 * Every suppression is a thing the health check is deliberately not checking.
 * That is legitimate, and it is also exactly how a health check dies: one "just
 * this one" at a time, silently, until the suite is green because it stopped
 * looking rather than because the pages are sound. The storefront lost five
 * phases of client-side coverage to a single unexamined entry.
 *
 * Counting does not prevent that. It makes it visible — the count is printed
 * whether the run passes or fails, each rule appears with the REASON the test
 * gave for it, and a rule that starts firing announces itself by its own source
 * text the first time it does.
 *
 * The reporter never fails a run. Deciding that a number is too high is a
 * judgement for a person, and a reporter that started failing builds on a
 * threshold nobody agreed would just be another thing to suppress.
 */

const ATTACHMENT = 'browser-health-suppressed';

interface Record {
  reason: string;
  count: number;
}

export default class HealthSummaryReporter implements Reporter {
  private readonly totals = new Map<string, Record>();
  private testsWithSuppressions = 0;

  onTestEnd(_test: TestCase, result: TestResult): void {
    const attachment = result.attachments.find((a) => a.name === ATTACHMENT);
    if (attachment?.body === undefined) return;

    let counts: Record_Map;
    try {
      counts = JSON.parse(attachment.body.toString('utf8')) as Record_Map;
    } catch {
      // A malformed attachment is not worth failing a run over, and saying so
      // is more useful than a stack trace from a reporter.
      process.stdout.write('browser-health: could not read a suppression attachment\n');
      return;
    }

    this.testsWithSuppressions += 1;

    for (const [rule, record] of Object.entries(counts)) {
      const seen = this.totals.get(rule);

      this.totals.set(rule, {
        // The first reason wins. Two tests suppressing the same pattern for
        // different reasons is itself worth noticing, and the alternative —
        // concatenating them — makes the common case unreadable.
        reason: seen?.reason ?? record.reason,
        count: (seen?.count ?? 0) + record.count,
      });
    }
  }

  onEnd(_result: FullResult): void {
    if (this.totals.size === 0) {
      process.stdout.write('\nbrowser-health: nothing was ignored in this run.\n');
      return;
    }

    const total = [...this.totals.values()].reduce((sum, record) => sum + record.count, 0);

    const lines = [...this.totals.entries()]
      .sort((a, b) => b[1].count - a[1].count)
      .map(([rule, record]) => `  ${String(record.count).padStart(5)}  /${rule}/\n         ${record.reason}`);

    process.stdout.write(
      `\nbrowser-health: ignored ${String(total)} browser problem(s) ` +
        `across ${String(this.testsWithSuppressions)} test(s), by rule:\n` +
        `${lines.join('\n')}\n` +
        'Each line is something the health check did NOT check, with the reason the\n' +
        'test gave. If a rule you do not recognise appears here, or a count grows,\n' +
        'that is the signal to look.\n',
    );
  }
}

/** The attachment's shape. Mirrors `SuppressionCounts` in the fixture. */
type Record_Map = globalThis.Record<string, Record>;

'use server'

import { createClient } from '@/lib/supabase'
import { requireAdminActor } from '@/lib/api/identity'
import { logAdminAction } from '@/lib/audit/log-action'
import { logger } from '@/lib/logger'
import { revalidatePath } from 'next/cache'
import { z } from 'zod'

const couponSchema = z.object({
  code: z.string().min(1, 'Code is required').max(50),
  type: z.enum(['percentage', 'fixed']),
  value: z.number().min(0),
  min_order: z.number().min(0).nullable().optional(),
  max_discount: z.number().min(0).nullable().optional(),
  usage_limit: z.number().int().min(0).nullable().optional(),
  starts_at: z.string().nullable().optional(),
  expires_at: z.string().nullable().optional(),
  is_active: z.boolean().default(true),
})

export async function createCouponAction(formData: FormData) {
  const admin = await requireAdminActor()
  const supabase = await createClient()

  const raw = {
    code: (formData.get('code') as string)?.trim().toUpperCase(),
    type: formData.get('type') as string,
    value: parseFloat(formData.get('value') as string) || 0,
    min_order: formData.get('min_order') ? parseFloat(formData.get('min_order') as string) : null,
    max_discount: formData.get('max_discount') ? parseFloat(formData.get('max_discount') as string) : null,
    usage_limit: formData.get('usage_limit') ? parseInt(formData.get('usage_limit') as string, 10) : null,
    starts_at: (formData.get('starts_at') as string) || null,
    expires_at: (formData.get('expires_at') as string) || null,
    is_active: formData.get('is_active') === 'true',
  }

  const parsed = couponSchema.safeParse(raw)
  if (!parsed.success) {
    const messages = parsed.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`).join(', ')
    return { success: false, error: messages }
  }

  try {
    const { data, error } = await (supabase as any)
      .from('coupons')
      .insert({ ...parsed.data, used_count: 0 })
      .select('id')
      .single()

    if (error || !data) {
      return { success: false, error: error?.message ?? 'Failed to create coupon' }
    }

    await logAdminAction({
      adminId: admin.id,
      action: 'coupon:create',
      entityType: 'coupon',
      entityId: data.id,
      changes: parsed.data,
    })

    revalidatePath('/admin/coupons')
    logger.info(`Coupon created: id=${data.id} code=${parsed.data.code} by=${admin.id}`)
    return { success: true, couponId: data.id }
  } catch (e) {
    logger.error('createCouponAction failed', e)
    return { success: false, error: 'Internal server error' }
  }
}

export async function updateCouponAction(formData: FormData) {
  const admin = await requireAdminActor()
  const supabase = await createClient()

  const id = formData.get('id') as string
  if (!id) return { success: false, error: 'Coupon ID is required' }

  const raw = {
    code: (formData.get('code') as string)?.trim().toUpperCase(),
    type: formData.get('type') as string,
    value: parseFloat(formData.get('value') as string) || 0,
    min_order: formData.get('min_order') ? parseFloat(formData.get('min_order') as string) : null,
    max_discount: formData.get('max_discount') ? parseFloat(formData.get('max_discount') as string) : null,
    usage_limit: formData.get('usage_limit') ? parseInt(formData.get('usage_limit') as string, 10) : null,
    starts_at: (formData.get('starts_at') as string) || null,
    expires_at: (formData.get('expires_at') as string) || null,
    is_active: formData.get('is_active') === 'true',
  }

  const parsed = couponSchema.safeParse(raw)
  if (!parsed.success) {
    const messages = parsed.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`).join(', ')
    return { success: false, error: messages }
  }

  try {
    const { error } = await (supabase as any)
      .from('coupons')
      .update(parsed.data)
      .eq('id', id)

    if (error) {
      return { success: false, error: error.message }
    }

    await logAdminAction({
      adminId: admin.id,
      action: 'coupon:update',
      entityType: 'coupon',
      entityId: id,
      changes: parsed.data,
    })

    revalidatePath('/admin/coupons')
    logger.info(`Coupon updated: id=${id} by=${admin.id}`)
    return { success: true }
  } catch (e) {
    logger.error('updateCouponAction failed', e)
    return { success: false, error: 'Internal server error' }
  }
}

export async function toggleCouponActiveAction(id: string, isActive: boolean) {
  const admin = await requireAdminActor()
  const supabase = await createClient()

  try {
    const { error } = await (supabase as any)
      .from('coupons')
      .update({ is_active: isActive })
      .eq('id', id)

    if (error) {
      return { success: false, error: error.message }
    }

    await logAdminAction({
      adminId: admin.id,
      action: isActive ? 'coupon:activate' : 'coupon:deactivate',
      entityType: 'coupon',
      entityId: id,
    })

    revalidatePath('/admin/coupons')
    logger.info(`Coupon ${isActive ? 'activated' : 'deactivated'}: id=${id} by=${admin.id}`)
    return { success: true }
  } catch (e) {
    logger.error('toggleCouponActiveAction failed', e)
    return { success: false, error: 'Internal server error' }
  }
}

export async function deleteCouponAction(id: string) {
  const admin = await requireAdminActor()
  const supabase = await createClient()

  try {
    const { error } = await (supabase as any)
      .from('coupons')
      .delete()
      .eq('id', id)

    if (error) {
      return { success: false, error: error.message }
    }

    await logAdminAction({
      adminId: admin.id,
      action: 'coupon:delete',
      entityType: 'coupon',
      entityId: id,
    })

    revalidatePath('/admin/coupons')
    logger.info(`Coupon deleted: id=${id} by=${admin.id}`)
    return { success: true }
  } catch (e) {
    logger.error('deleteCouponAction failed', e)
    return { success: false, error: 'Internal server error' }
  }
}

'use server'

import { createClient } from '@/lib/supabase'
import { requireAdminActor } from '@/lib/api/identity'
import { logAdminAction } from '@/lib/audit/log-action'
import { logger } from '@/lib/logger'
import { revalidatePath } from 'next/cache'
import { z } from 'zod'

const reviewStatusSchema = z.object({
  reviewId: z.string().uuid(),
  status: z.enum(['pending', 'approved', 'rejected']),
})

export async function updateReviewStatusAction(formData: FormData) {
  const admin = await requireAdminActor()
  const supabase = await createClient()

  const raw = {
    reviewId: formData.get('reviewId') as string,
    status: formData.get('status') as string,
  }

  const parsed = reviewStatusSchema.safeParse(raw)
  if (!parsed.success) {
    const messages = parsed.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`).join(', ')
    return { success: false, error: messages }
  }

  try {
    const { error } = await (supabase as any)
      .from('reviews')
      .update({ moderation_status: parsed.data.status })
      .eq('id', parsed.data.reviewId)

    if (error) {
      return { success: false, error: error.message }
    }

    await logAdminAction({
      adminId: admin.id,
      action: `review:${parsed.data.status}`,
      entityType: 'review',
      entityId: parsed.data.reviewId,
      changes: { moderation_status: parsed.data.status },
    })

    revalidatePath('/admin/reviews')
    logger.info(`Review ${parsed.data.status}: id=${parsed.data.reviewId} by=${admin.id}`)
    return { success: true }
  } catch (e) {
    logger.error('updateReviewStatusAction failed', e)
    return { success: false, error: 'Internal server error' }
  }
}

export async function deleteReviewAction(reviewId: string) {
  const admin = await requireAdminActor()
  const supabase = await createClient()

  try {
    const { error } = await (supabase as any)
      .from('reviews')
      .delete()
      .eq('id', reviewId)

    if (error) {
      return { success: false, error: error.message }
    }

    await logAdminAction({
      adminId: admin.id,
      action: 'review:delete',
      entityType: 'review',
      entityId: reviewId,
    })

    revalidatePath('/admin/reviews')
    logger.info(`Review deleted: id=${reviewId} by=${admin.id}`)
    return { success: true }
  } catch (e) {
    logger.error('deleteReviewAction failed', e)
    return { success: false, error: 'Internal server error' }
  }
}

import { PageHeader, ErrorState } from '@/components/ui/admin';
import { requireAdmin, getAdminServices } from '@/lib/services';
import { DomainNotLiveNotice } from '@/components/system/DomainNotLiveNotice';
import { Suspense } from 'react';
import { CouponsTable } from '@/components/coupons/CouponsTable';

function CouponsSkeleton() {
  return (
    <div className="space-y-5 animate-pulse">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        {Array.from({ length: 4 }).map((_, i) => (
          <div key={i} className="rounded-xl border border-border bg-card p-4 h-20" />
        ))}
      </div>
      <div className="rounded-xl border border-border bg-card h-12" />
      <div className="rounded-xl border border-border bg-card h-96" />
    </div>
  );
}

export default async function CouponsPage(props: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  await requireAdmin();
  const { supabase } = await getAdminServices();
  const sp = await props.searchParams;

  const page = Number(sp.page) || 1;
  const search = (sp.search as string) || '';
  const statusFilter = (sp.status as string) || '';
  const limit = 25;

  let query = (supabase as any)
    .from('coupons')
    .select('*', { count: 'exact' });

  if (search) {
    query = query.ilike('code', `%${search}%`);
  }
  if (statusFilter === 'active') {
    query = query.eq('is_active', true);
  } else if (statusFilter === 'inactive') {
    query = query.eq('is_active', false);
  } else if (statusFilter === 'expired') {
    query = query.lt('expires_at', new Date().toISOString());
  }

  const { data, count, error } = await query
    .range((page - 1) * limit, page * limit - 1)
    .order('created_at', { ascending: false });

  const coupons = (data ?? []) as Array<{
    id: string;
    code: string;
    type: string;
    value: number;
    min_order: number | null;
    max_discount: number | null;
    usage_limit: number | null;
    used_count: number | null;
    starts_at: string | null;
    expires_at: string | null;
    is_active: boolean | null;
  }>;

  const total = count ?? 0;
  const totalPages = Math.ceil(total / limit);

  /* Stats */
  const { count: totalCount } = await (supabase as any)
    .from('coupons')
    .select('*', { count: 'exact', head: true });

  const { count: activeCount } = await (supabase as any)
    .from('coupons')
    .select('*', { count: 'exact', head: true })
    .eq('is_active', true);

  const { count: expiredCount } = await (supabase as any)
    .from('coupons')
    .select('*', { count: 'exact', head: true })
    .lt('expires_at', new Date().toISOString());

  const { data: usedData } = await (supabase as any)
    .from('coupons')
    .select('used_count');
  const totalUsed = (usedData ?? []).reduce((sum: number, c: any) => sum + (c.used_count ?? 0), 0);

  return (
    <div className="space-y-5">
      <DomainNotLiveNotice domain="coupons" />

      <PageHeader title={<>Coupons</>} description={<>Create and manage promotional coupon codes.</>} />

      {error ? <ErrorState title="Coupons could not be loaded" description="The legacy service did not respond. Try again in a moment." /> : <Suspense fallback={<CouponsSkeleton />}>
