                <th className="px-5 py-3 text-center text-[11px] font-bold text-muted-foreground uppercase tracking-wider">Status</th>
                <th className="px-5 py-3 text-right text-[11px] font-bold text-muted-foreground uppercase tracking-wider">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {coupons.length === 0 ? (
                <tr>
                  <td colSpan={7} className="px-5 py-12 text-center">
                    <div className="flex flex-col items-center gap-2">
                      <Ticket className="h-8 w-8 text-muted-foreground/40" />
                      <p className="text-sm font-medium text-muted-foreground">
                        {hasFilters ? 'No coupons match your search' : 'No coupons yet'}
                      </p>
                      <p className="text-xs text-muted-foreground/60">
                        {hasFilters ? 'Try a different search term.' : 'Create your first promotional coupon.'}
                      </p>
                    </div>
                  </td>
                </tr>
              ) : (
                coupons.map((coupon) => {
                  const status = getCouponStatus(coupon);
                  const isLoading = actionId === coupon.id;
                  const usage = coupon.used_count ?? 0;
                  const limit = coupon.usage_limit;
                  const usagePercent = limit && limit > 0 ? Math.min((usage / limit) * 100, 100) : 0;

                  return (
                    <tr key={coupon.id} className="hover:bg-muted/20 transition-colors group">
                      <td className="px-5 py-3">
                        <div className="flex items-center gap-2">
                          <div className="h-8 w-8 rounded-lg border border-border bg-muted flex items-center justify-center shrink-0">
                            <Hash className="h-3.5 w-3.5 text-muted-foreground/50" />
                          </div>
                          <span className="text-sm font-bold text-foreground font-mono">{coupon.code}</span>
                        </div>
                      </td>
                      <td className="px-5 py-3">
                        <span className="inline-flex items-center gap-1 text-xs text-muted-foreground">
                          {coupon.type === 'percentage' ? <Percent className="h-3 w-3" /> : <Tag className="h-3 w-3" />}
                          {coupon.type === 'percentage' ? 'Percentage' : 'Fixed'}
                        </span>
                      </td>
                      <td className="px-5 py-3 text-right">
                        <span className="text-sm font-bold text-foreground tabular-nums">
                          {coupon.type === 'percentage' ? `${coupon.value}%` : `EGP ${coupon.value.toLocaleString('en-EG')}`}
                        </span>
                      </td>
                      <td className="px-5 py-3 text-right">
                        <div className="flex flex-col items-end gap-1">
                          <span className="text-xs font-bold text-foreground tabular-nums">
                            {usage}{limit ? ` / ${limit}` : ''}
                          </span>
                          {limit && limit > 0 && (
                            <div className="w-16 h-1 rounded-full bg-muted overflow-hidden">
                              <div className="h-full rounded-full bg-primary" style={{ width: `${Math.max(usagePercent, 4)}%` }} />
                            </div>
                          )}
                        </div>
                      </td>
                      <td className="px-5 py-3">
                        <div className="flex flex-col gap-0.5 text-[11px] text-muted-foreground">
                          <span>{coupon.starts_at ? `From ${formatDate(coupon.starts_at)}` : 'No start date'}</span>
                          <span>{coupon.expires_at ? `Until ${formatDate(coupon.expires_at)}` : 'No expiry'}</span>
                        </div>
                      </td>
                      <td className="px-5 py-3 text-center">
                        <StatusBadge status={status.status} />
                      </td>
                      <td className="px-5 py-3 text-right">
                        <div className="flex items-center justify-end gap-0.5 opacity-60 group-hover:opacity-100 transition-opacity">
                          <button
                            onClick={() => startEdit(coupon)}
                            className="inline-flex items-center justify-center rounded-md p-1.5 text-muted-foreground hover:bg-primary/10 hover:text-primary transition-all"
                            title="Edit"
                          >
                            <Pencil className="w-3.5 h-3.5" />
                          </button>
                          <button
                            onClick={() => handleToggleActive(coupon)}
                            disabled={isLoading}
                            className={`inline-flex items-center justify-center rounded-md p-1.5 transition-all ${coupon.is_active ? 'text-muted-foreground hover:bg-warning/10 hover:text-warning' : 'text-muted-foreground hover:bg-success/10 hover:text-success'}`}
                            title={coupon.is_active ? 'Deactivate' : 'Activate'}
                          >
                            {isLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : coupon.is_active ? <XCircle className="w-3.5 h-3.5" /> : <CheckCircle2 className="w-3.5 h-3.5" />}
                          </button>
                          <button
                            onClick={() => handleDelete(coupon.id)}
                            disabled={isLoading}
                            className="inline-flex items-center justify-center rounded-md p-1.5 text-muted-foreground hover:bg-destructive/10 hover:text-destructive transition-all"
                            title="Delete"
                          >
                            {isLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Trash2 className="w-3.5 h-3.5" />}
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </TableScroll>
        <div className="px-5 py-3 border-t border-border bg-muted/20 flex flex-wrap items-center justify-between gap-3">
          <span className="text-xs text-muted-foreground">
            Showing <span className="font-semibold text-foreground">{coupons.length}</span> of <span className="font-semibold text-foreground">{total}</span> coupons
          </span>
          {totalPages > 1 && (
            <Pagination currentPage={currentPage} totalPages={totalPages} onPageChange={handlePageChange} />
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { TableScroll, StatCard } from '@/components/ui/admin';


import { useState, useTransition, useEffect } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import Image from 'next/image';
import { Pagination } from '@nest/ui';
import {
  Search, X, Users, User, UserPlus, ShoppingBag, CreditCard, Calendar,
  Loader2, ChevronDown, Filter, Phone, Mail
} from 'lucide-react';

interface Customer {
  id: string;
  full_name: string;
  phone: string | null;
  avatar_url: string | null;
  created_at: string;
}

/**
 * What one customer has spent, as the SERVER formatted it.
 *
 * `total` used to be `totalSpent` — a number the API documents as *"lifetime
 * spend in MINOR UNITS"* — printed as `EGP {total.toLocaleString()}`. Every row
 * on this screen showed a hundred times the real figure: fifty pounds as
 * "EGP 5,000".
 *
 * It is the same defect the stat strip above the table had, found the same way
 * and one commit apart, which is why there is now a test that scans for the
 * shape rather than a resolution to be careful. `AdminCustomerSummary` carries
 * `formattedTotalSpent` for exactly this, and that is what crosses the boundary
 * now — a string, so there is nothing left to divide by anything.
 */
interface CustomerOrderStats {
  count: number;
  /** Pre-formatted by the server, e.g. `"325.00 EGP"`. */
  spent: string;
}

interface CustomersTableProps {
  initialCustomers: Customer[];
  orderMap: Record<string, CustomerOrderStats>;
  currentPage: number;
  totalPages: number;
  total: number;
  stats: {
    total: number;
    newThisWeek: number | null;
    /** Customers who ordered INSIDE the window — not "have ever ordered". */
    withOrders: number | null;
    /**
     * The SERVER's formatted money string, never an amount to format here.
     *
     * It used to be `revenue.delivered.amount` printed as
     * `EGP ${amount.toLocaleString()}` — and `amount` is in PIASTRES, so a card
     * reading "EGP 5,000" was 50 EGP. Money crosses this boundary formatted or
     * it disagrees with the invoice.
     */
    revenueFormatted: string;
    /** The period the two windowed figures cover, as the server labelled it. */
    windowLabel: string | null;
  };
}

function formatDate(dateString: string) {
  const d = new Date(dateString);
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

export function CustomersTable({ initialCustomers, orderMap, currentPage, totalPages, total, stats }: CustomersTableProps) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [isPending, startTransition] = useTransition();
  const [searchInput, setSearchInput] = useState(searchParams.get('search') || '');

  const search = searchParams.get('search') || '';
  const hasFilters = !!search;

  useEffect(() => {
    if (searchInput === search) return;
    const timer = setTimeout(() => {
      const params = new URLSearchParams(searchParams.toString());
      if (searchInput) {
        params.set('search', searchInput);
      } else {
        params.delete('search');
      }
      params.set('page', '1');
      startTransition(() => {
        router.push(`/customers?${params.toString()}`);
      });
    }, 350);
    return () => clearTimeout(timer);
  }, [searchInput, search, router, searchParams]);

  const handlePageChange = (page: number) => {
    const params = new URLSearchParams(searchParams.toString());
    params.set('page', String(page));
    startTransition(() => {
      router.push(`/customers?${params.toString()}`);
    });
  };

  const clearAllFilters = () => {
    startTransition(() => {
      router.push('/customers');
    });
  };

  /*
   * Two of these four are bounded by the dashboard's trailing window and two
   * are not, so the two that are say so under the number. An unlabelled "With
   * Orders" beside an unlabelled "Total Customers" invites the reader to divide
   * one by the other, and over a 30-day window that ratio means something quite
   * different from what it looks like.
   */
  const statItems = [
    { label: 'Total Customers', value: stats.total, icon: Users, color: 'primary' as const, caption: 'All registered accounts' },
    { label: 'New This Week', value: stats.newThisWeek, icon: UserPlus, color: 'success' as const, caption: 'Registered in the last 7 days' },
    { label: 'Ordered', value: stats.withOrders, icon: ShoppingBag, color: 'warning' as const, caption: stats.windowLabel },
    { label: 'Delivered Revenue', value: stats.revenueFormatted, icon: CreditCard, color: 'primary' as const, caption: stats.windowLabel },
  ];

  return (
    <div className="space-y-5">
      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3">
        {statItems.map((item) => {
          const Icon = item.icon;
          return (
            <StatCard key={item.label} label={item.label} value={item.value ?? "—"} icon={<Icon />} description={item.caption} tone="sage" />
          );
        })}
      </div>

      {/* Toolbar */}
      <div className="rounded-xl border border-border bg-card shadow-sm p-4 space-y-3">
        <div className="flex flex-wrap items-center gap-3">
          <div className="relative flex-1 min-w-[240px]">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <input
              type="text"
              aria-label="Search customers by name or phone"
              placeholder="Search by name or phone..."
              value={searchInput}
              className="h-10 w-full rounded-lg border border-border bg-background pl-10 pr-4 text-sm focus:ring-2 focus:ring-primary/10 transition-all outline-none"
              onChange={(e) => setSearchInput(e.target.value)}
            />
            {searchInput && (
              <button
                onClick={() => setSearchInput('')}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              >
                <X className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
          {hasFilters && (
            <button onClick={clearAllFilters} className="inline-flex items-center gap-1.5 rounded-lg border border-border bg-background px-3 py-2 text-xs font-semibold text-muted-foreground hover:bg-muted hover:text-foreground transition-all">
              <X className="h-3.5 w-3.5" /> Clear
            </button>
          )}
        </div>
        {isPending && (
          <div className="flex items-center gap-2 text-xs text-muted-foreground animate-pulse">
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
            Updating results...
          </div>
        )}
      </div>

      {/* Table */}
      <div className="rounded-xl border border-border bg-card shadow-sm overflow-hidden">
        <TableScroll>
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/30 border-b border-border">
                <th className="px-5 py-3 text-left text-[11px] font-bold text-muted-foreground uppercase tracking-wider">Customer</th>
                <th className="px-5 py-3 text-left text-[11px] font-bold text-muted-foreground uppercase tracking-wider">Contact</th>
                <th className="px-5 py-3 text-right text-[11px] font-bold text-muted-foreground uppercase tracking-wider">Orders</th>
                <th className="px-5 py-3 text-right text-[11px] font-bold text-muted-foreground uppercase tracking-wider">Total Spent</th>
                <th className="px-5 py-3 text-right text-[11px] font-bold text-muted-foreground uppercase tracking-wider">Joined</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {initialCustomers.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-5 py-12 text-center">
                    <div className="flex flex-col items-center gap-2">
                      <Users className="h-8 w-8 text-muted-foreground/40" />
                      <p className="text-sm font-medium text-muted-foreground">
                        {hasFilters ? 'No customers match your search' : 'No customers yet'}
                      </p>
                      <p className="text-xs text-muted-foreground/60">
                        {hasFilters ? 'Try a different search term.' : 'Customer accounts will appear here.'}
                      </p>
                    </div>
                  </td>
                </tr>
              ) : (
                initialCustomers.map((customer) => {
                  const stats = orderMap[customer.id] ?? { count: 0, spent: '—' };
                  return (
                    <tr key={customer.id} className="hover:bg-muted/20 transition-colors">
                      <td className="px-5 py-3">
                        <div className="flex items-center gap-3">
                          <div className="h-9 w-9 rounded-full border border-border bg-muted flex items-center justify-center shrink-0 overflow-hidden">
                            {customer.avatar_url ? (
                              <Image src={customer.avatar_url} alt="" width={36} height={36} className="object-cover" />
                            ) : (
                              <User className="h-4 w-4 text-muted-foreground/50" />
                            )}
                          </div>
                          <span className="text-sm font-semibold text-foreground">{customer.full_name}</span>
                        </div>
                      </td>
                      <td className="px-5 py-3">
                        <div className="flex flex-col gap-0.5">
                          {customer.phone && (
                            <span className="inline-flex items-center gap-1 text-xs text-muted-foreground">
                              <Phone className="h-3 w-3" /> {customer.phone}
                            </span>
                          )}
                        </div>
                      </td>
                      <td className="px-5 py-3 text-right">
                        <span className="text-sm font-bold text-foreground tabular-nums">{stats.count}</span>
                      </td>
                      <td className="px-5 py-3 text-right">
                        {/* The server's own string. Never an amount and a symbol. */}
                        <span className="text-sm font-bold text-foreground tabular-nums">
                          {stats.spent}
                        </span>
                      </td>
                      <td className="px-5 py-3 text-right">
                        <span className="inline-flex items-center gap-1 text-[11px] text-muted-foreground">
                          <Calendar className="h-3 w-3" />
                          {formatDate(customer.created_at)}
                        </span>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </TableScroll>
        <div className="px-5 py-3 border-t border-border bg-muted/20 flex flex-wrap items-center justify-between gap-3">
          <span className="text-xs text-muted-foreground">
            Showing <span className="font-semibold text-foreground">{initialCustomers.length}</span> of <span className="font-semibold text-foreground">{total}</span> customers
          </span>
          {totalPages > 1 && (
            <Pagination currentPage={currentPage} totalPages={totalPages} onPageChange={handlePageChange} />
          )}
        </div>
      </div>
    </div>
  );
}

